thread_local char t_DataStringBuffer[10240];
 
NotifyComponentConnectStatusPackage::NotifyComponentConnectStatusPackage()
	:NotifyComponentConnectStatus(nullptr)
{
}
NotifyComponentConnectStatusPackage::~NotifyComponentConnectStatusPackage()
{
	if (NotifyComponentConnectStatus != nullptr)
	{
		ObjectPool<NotifyComponentConnectStatusField>::GetInstance().Deallocate(NotifyComponentConnectStatus);
		NotifyComponentConnectStatus = nullptr;
	}
}
NotifyComponentConnectStatusPackage* NotifyComponentConnectStatusPackage::Allocate()
{
	return ObjectPool<NotifyComponentConnectStatusPackage>::GetInstance().Allocate();
}
void NotifyComponentConnectStatusPackage::Deallocate()
{
	ObjectPool<NotifyComponentConnectStatusPackage>::GetInstance().Deallocate(this);
}
void NotifyComponentConnectStatusPackage::Prepare(SessionIDType sessionID, int messageChain, int msgSeqNum)
{
	Package::Prepare(sessionID, messageChain, msgSeqNum);
	Head.PackageID = PackageID;
}
int NotifyComponentConnectStatusPackage::ToStepStream(char* buff, int size) const
{
	StepWriteCursor cursor(buff, size);
	if (NotifyComponentConnectStatus != nullptr)
	{
		StepUtility::WriteHexString(cursor, Items::FieldStart, NotifyComponentConnectStatusField::FieldID);
		StepUtility::WriteString(cursor, Items::SessionID, NotifyComponentConnectStatus->SessionID);
		StepUtility::WriteString(cursor, Items::Component, static_cast<int>(NotifyComponentConnectStatus->Component));
		StepUtility::WriteString(cursor, Items::IsConnected, NotifyComponentConnectStatus->IsConnected);
		StepUtility::WriteHexString(cursor, Items::FieldEnd, NotifyComponentConnectStatusField::FieldID);
	}
	if (cursor.IsTruncated())
	{
		return -1;
	}
	return cursor.GetWrittenLength();
}
bool NotifyComponentConnectStatusPackage::FromStepStream(char* buff, int startIndex, int endIndex)
{
	while (startIndex < endIndex)
	{
		unsigned short fieldID;
		int fieldStartIndex;
		int fieldEndIndex;
		if (StepUtility::GetNextFieldZone(buff, startIndex, endIndex, fieldID, fieldStartIndex, fieldEndIndex))
		{
			int itemStartIndex = fieldStartIndex;
			switch (fieldID)
			{
			case NotifyComponentConnectStatusField::FieldID:
			{
				NotifyComponentConnectStatus = ObjectPool<NotifyComponentConnectStatusField>::GetInstance().Allocate();
				memset(NotifyComponentConnectStatus, 0, sizeof(*NotifyComponentConnectStatus));
				while (itemStartIndex < fieldEndIndex)
				{
					unsigned short  itemID;
					std::string value;
					int sohIndex;
					if (StepUtility::GetNext(buff, itemStartIndex, fieldEndIndex, itemID, value, sohIndex))
					{
						switch (itemID)
						{
						case Items::FieldStart:
						case Items::FieldEnd:
							break;
						case Items::SessionID:
						{
							NotifyComponentConnectStatus->SessionID = atoll(value.c_str());
							break;
						}
						case Items::Component:
						{
							NotifyComponentConnectStatus->Component = static_cast<ComponentType>(atoi(value.c_str()));
							break;
						}
						case Items::IsConnected:
						{
							NotifyComponentConnectStatus->IsConnected = atoi(value.c_str());
							break;
						}
						default:
							WriteLog(LogLevel::Warning, "Unexpected ItemID:0x%X for NotifyComponentConnectStatusField FieldID:0x%X, Please Check ApiVersion.", itemID, fieldID);
							return false;
						}
						itemStartIndex = sohIndex + 1;
					}
					else
					{
						WriteLog(LogLevel::Warning, "GetNext Failed For NotifyComponentConnectStatusPackage FieldID:0x%X", fieldID);
						return false;
					}
				}
				break;
			}
			default:
				WriteLog(LogLevel::Warning, "Unexpected FieldID:0x%X, Please Check Api Version.", fieldID);
				return false;
			}
			startIndex = fieldEndIndex;
		}
		else
		{
			WriteLog(LogLevel::Warning, "GetNextFieldZone Failed For NotifyComponentConnectStatusPackage");
			return false;
		}
	}
	return true;
}
int NotifyComponentConnectStatusPackage::ToXtpStream(char* buff, int size) const
{
	int offset = 0;
	if (NotifyComponentConnectStatus != nullptr)
	{
		const int fieldSize = static_cast<int>(sizeof(UInt16Type) + sizeof(NotifyComponentConnectStatusField));
		if (offset + fieldSize > size)
		{
			return -1;
		}
		memcpy(buff + offset, &NotifyComponentConnectStatusField::FieldID, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		memcpy(buff + offset, NotifyComponentConnectStatus, sizeof(NotifyComponentConnectStatusField));
		offset += sizeof(NotifyComponentConnectStatusField);
	}
	return offset;
}
bool NotifyComponentConnectStatusPackage::FromXtpStream(char* buff, int startIndex, int endIndex)
{
	int offset = startIndex;
	while(offset < endIndex)
	{
		UInt16Type fieldID = 0;
		memcpy(&fieldID, buff + offset, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		switch (fieldID)
		{
		case NotifyComponentConnectStatusField::FieldID:
		{
			NotifyComponentConnectStatus = ObjectPool<NotifyComponentConnectStatusField>::GetInstance().Allocate();
			memcpy(NotifyComponentConnectStatus, buff + offset, sizeof(NotifyComponentConnectStatusField));
			offset += sizeof(NotifyComponentConnectStatusField);	
			break;
		}
		default:
			return false;
		}
	}
	return offset == endIndex;
}
const char* NotifyComponentConnectStatusPackage::GetDebugString() const
{
	int offset = 0;
	if (NotifyComponentConnectStatus != nullptr)
	{
		offset += sprintf(t_DataStringBuffer + offset, "NotifyComponentConnectStatus:SessionID:[%lld], Component:[%d], IsConnected:[%d]", NotifyComponentConnectStatus->SessionID, static_cast<int>(NotifyComponentConnectStatus->Component), NotifyComponentConnectStatus->IsConnected);
	}
	return t_DataStringBuffer;
}
 
