		{
			return -1;
		}
		memcpy(buff + offset, &RspMoneyTransferField::FieldID, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		memcpy(buff + offset, RspMoneyTransfer, sizeof(RspMoneyTransferField));
		offset += sizeof(RspMoneyTransferField);
